      "id": "CPY-28",
      "formulaId": "UX-04",
      "name": "Friction-Reducing Reassurances",
      "phase": "Product Microcopy",
      "surface": "Form Terminus, Checkout Under-buttons",
      "mechanism": "Ambiguity Aversion & Perceived Risk Defusal",
      "scope": "Grade 4–6; Micro-string (4–12 words)",
