      "svg": "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 400 400\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\" aria-label=\"Parametric diagram of the card principle\"><path d=\"M 56 166 L 80 234 L 104 166 L 128 234 L 152 166 L 176 234 L 200 194 L 224 206 L 248 194 L 272 206 L 296 194 L 320 206 L 344 194\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.2\" opacity=\"0.7\" vector-effect=\"non-scaling-stroke\"/><line x1=\"92\" y1=\"64\" x2=\"92\" y2=\"336\" stroke=\"currentColor\" stroke-width=\"1.1\" stroke-linecap=\"round\" stroke-dasharray=\"6 8\" opacity=\"0.18\" vector-effect=\"non-scaling-stroke\"/><circle cx=\"92\" cy=\"194\" r=\"6\" fill=\"currentColor\" stroke=\"currentColor\" stroke-width=\"1.8\" opacity=\"0.95\" vector-effect=\"non-scaling-stroke\"/></svg>"
